+import { reply_choice } from "./reply_choice.mjs";
+import { reply_words } from "./reply_words.mjs";
+import { reply_sequence } from "./reply_sequence.mjs";
+import { reply_word_that_the } from "./reply_word_that_the.mjs";
+import { reply_word_charity_love } from "./reply_word_charity_love.mjs";
+import { reply_word_god } from "./reply_word_god.mjs";
+import { reply_word_love } from "./reply_word_love.mjs";
+import { reply_word_us } from "./reply_word_us.mjs";
+export function reply_phrase_love_shown() {
+  "God's love was shown to us, in the words of 1 John 4:9. Bibles put the love before, after, or inside was shown, and one puts us first.";
+  let r2 = reply_words("in this");
+  let r3 = reply_words("by this");
+  let r4 = reply_words("this is how");
+  let opener = reply_choice(["herein", r2, r3, r4, "and"]);
+  let r5 = reply_word_that_the();
+  let r6 = reply_word_charity_love();
+  let v = reply_word_god();
+  let love_of_god = reply_sequence([r5, r6, "of", v]);
+  let fn = reply_choice(["gods", "god's"]);
+  let r7 = reply_word_love();
+  let gods_love = reply_sequence([fn, r7]);
+  let love = reply_choice([love_of_god, gods_love]);
+  let r8 = reply_words("has been");
+  let was = reply_choice(["was", "hath", r8]);
+  let r9 = reply_words("made manifest");
+  let r10 = reply_words("made clear");
+  let shown = reply_choice(["manifested", r9, r10, "revealed", "appeared"]);
+  let was_shown = reply_sequence([was, shown]);
+  let was_shown_love = reply_sequence([was_shown, love]);
+  let love_was_shown = reply_sequence([love, was_shown]);
+  let was_love_shown = reply_sequence([was, love, shown]);
+  let us = reply_word_us();
+  let to = reply_choice(["to", "toward", "towards", "in", "among", "amongst"]);
+  let to_us = reply_sequence([to, us]);
+  let fn2 = reply_choice([was_shown_love, love_was_shown, was_love_shown]);
+  let love_then_us = reply_sequence([fn2, to_us]);
+  let r11 = reply_words("as to");
+  let us_then_love = reply_sequence([r11, us, was_shown_love]);
+  let fn3 = reply_choice([love_then_us, us_then_love]);
+  let r = reply_sequence([opener, fn3]);
+  return r;
+}
